import {
  BaseSheet,
  CreateFilterOperation,
  FilterOn,
  Operation,
  RemoveFilterOperation,
  Sheet,
  UpdateFilterOperation,
} from '@bzl/sheet-js';
import { SheetOTType } from '@bzl/sheet-ottype';
import { afterEach, describe, expect, test, beforeEach } from 'vitest';
import { initialDoc } from '../utils';

describe('left side to 【update-filter】, right side to', () => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: UpdateFilterOperation = {
    type: 'update-filter',
    col: 8,
    rule: {
      on: FilterOn.VALUE,
      values: ['1', '2'],
    },
    id: '1',
  };
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', JSON.stringify(op12));
    console.log('op21,', JSON.stringify(op21));

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', JSON.stringify(doc1));
    console.log('doc2,', JSON.stringify(doc2));
    expect(doc1).toEqual(doc2);
  });

  test('【remove-filter】', () => {
    op2 = {
      type: 'remove-filter',
      id: '1',
    } as RemoveFilterOperation;
  });

  test('【create-filter】', () => {
    op2 = {
      type: 'create-filter',
      range: [6, 0, 8, Infinity],
      cols: [],
      id: '1',
    } as CreateFilterOperation;
  });

  test('【update-filter】', () => {
    op2 = {
      type: 'update-filter',
      col: 8,
      rule: {
        on: FilterOn.VALUE,
        values: ['1', '2'],
      },
      id: '1',
    } as UpdateFilterOperation;
  });
});
